 66→+// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
 67→+// and the raw transcript from /full/* refs (current + archived generations).
 68→+// If the transcript is not found in any /full/* ref, the returned SessionContent
 69→+// has an empty Transcript field — metadata and prompts are still populated.
 70→+func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
 71→+	if err := ctx.Err(); err != nil {
 72→+		return nil, err //nolint:wrapcheck // Propagating context cancellation
 73→+	}
 74→+
 75→+	refName := plumbing.ReferenceName(paths.V2MainRefName)
 76→+	_, rootTreeHash, err := s.getRefState(refName)
 77→+	if err != nil {
 78→+		return nil, ErrCheckpointNotFound
 79→+	}
 80→+
 81→+	rootTree, err := s.repo.TreeObject(rootTreeHash)
 82→+	if err != nil {
 83→+		return nil, ErrCheckpointNotFound
 84→+	}
 85→+
 86→+	cpTree, err := rootTree.Tree(checkpointID.Path())
 87→+	if err != nil {
 88→+		return nil, ErrCheckpointNotFound
 89→+	}
 90→+
 91→+	sessionDir := strconv.Itoa(sessionIndex)
 92→+	sessionTree, err := cpTree.Tree(sessionDir)
 93→+	if err != nil {
 94→+		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
 95→+	}
 96→+
 97→+	result := &SessionContent{}
 98→+
 99→+	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
100→+		if content, contentErr := metadataFile.Contents(); contentErr == nil {
101→+			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
102→+				return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
103→+			}
104→+		}
105→+	}
106→+
107→+	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
108→+		if content, contentErr := file.Contents(); contentErr == nil {
109→+			result.Prompts = content
110→+		}
111→+	}
112→+
113→+	transcript, _ := s.resolveTranscriptFromFull(ctx, checkpointID, sessionIndex) //nolint:errcheck // Missing transcript is not an error — caller handles empty transcript
114→+	result.Transcript = transcript
115→+
116→+	return result, nil
117→+}
118→+
119→+// resolveTranscriptFromFull searches /full/current then archived generations
120→+// for the raw transcript of a specific checkpoint session.
121→+func (s *V2GitStore) resolveTranscriptFromFull(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
122→+	if err := ctx.Err(); err != nil {
123→+		return nil, err //nolint:wrapcheck // Propagating context cancellation
124→+	}
125→+
126→+	sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
127→+
128→+	transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath)
129→+	if err == nil && len(transcript) > 0 {
130→+		return transcript, nil
131→+	}
132→+
133→+	archived, err := s.listArchivedGenerations()
134→+	if err != nil {
135→+		return nil, err
136→+	}
137→+	for i := len(archived) - 1; i >= 0; i-- {
138→+		refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
139→+		transcript, err := s.readTranscriptFromRef(refName, sessionPath)
140→+		if err == nil && len(transcript) > 0 {
141→+			return transcript, nil
142→+		}
143→+	}
144→+
145→+	return nil, nil
146→+}
147→+
148→+// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
149→+// Handles both chunked and non-chunked transcripts.
150→+func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string) ([]byte, error) {
151→+	_, rootTreeHash, err := s.getRefState(refName)
152→+	if err != nil {
153→+		return nil, err
154→+	}
155→+
156→+	rootTree, err := s.repo.TreeObject(rootTreeHash)
157→+	if err != nil {
158→+		return nil, fmt.Errorf("failed to read tree: %w", err)
159→+	}
160→+
161→+	sessionTree, err := rootTree.Tree(sessionPath)
162→+	if err != nil {
163→+		return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
164→+	}
165→+
166→+	file, err := sessionTree.File(paths.TranscriptFileName)
167→+	if err == nil {
168→+		content, contentErr := file.Contents()
169→+		if contentErr == nil {
170→+			return []byte(content), nil
171→+		}
172→+	}
173→+
174→+	return readChunkedTranscriptFromTree(sessionTree)
175→+}
176→+
177→+// readChunkedTranscriptFromTree reads and reassembles chunked transcript files from a tree.
178→+func readChunkedTranscriptFromTree(tree *object.Tree) ([]byte, error) {
179→+	var chunks []struct {
180→+		index int
181→+		name  string
182→+	}
183→+
184→+	for _, entry := range tree.Entries {
185→+		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
186→+			suffix := strings.TrimPrefix(entry.Name, paths.TranscriptFileName+".")
187→+			idx, err := strconv.Atoi(suffix)
188→+			if err == nil && idx > 0 {
189→+				chunks = append(chunks, struct {
190→+					index int
191→+					name  string
192→+				}{index: idx, name: entry.Name})
193→+			}
194→+		}
195→+	}
196→+
197→+	if len(chunks) == 0 {
198→+		return nil, errors.New("no transcript files found")
199→+	}
200→+
201→+	sort.Slice(chunks, func(i, j int) bool {
202→+		return chunks[i].index < chunks[j].index
203→+	})
204→+
205→+	var result []byte
206→+	for _, chunk := range chunks {
207→+		file, err := tree.File(chunk.name)
208→+		if err != nil {
209→+			return nil, fmt.Errorf("failed to read chunk %s: %w", chunk.name, err)
210→+		}
211→+		content, err := file.Contents()
212→+		if err != nil {
213→+			return nil, fmt.Errorf("failed to read chunk content %s: %w", chunk.name, err)
214→+		}
215→+		result = append(result, []byte(content)...)
216→+	}
217→+
218→+	return result, nil
219→+}
220→+
221→+// GetSessionLog reads the latest session's raw transcript and session ID from v2 refs.
222→+// Convenience wrapper matching the GitStore.GetSessionLog signature.
223→+func (s *V2GitStore) GetSessionLog(ctx context.Context, cpID id.CheckpointID) ([]byte, string, error) {
224→+	summary, err := s.ReadCommitted(ctx, cpID)
225→+	if err != nil {
226→+		return nil, "", err
227→+	}
228→+	if summary == nil {
229→+		return nil, "", ErrCheckpointNotFound
230→+	}
231→+	if len(summary.Sessions) == 0 {
232→+		return nil, "", ErrCheckpointNotFound
233→+	}
234→+
235→+	latestIndex := len(summary.Sessions) - 1
236→+	content, err := s.ReadSessionContent(ctx, cpID, latestIndex)
237→+	if err != nil {
238→+		return nil, "", err
239→+	}
240→+	if len(content.Transcript) == 0 {
241→+		return nil, "", ErrNoTranscript
242→+	}
243→+	return content.Transcript, content.Metadata.SessionID, nil
244→+}
